function getCats(){try{let a=JSON.parse(localStorage.getItem('gi-cats')||'null');if(Array.isArray(a))a=a.filter(c=>c&&c.key!='figurines');if(Array.isArray(a)&&a.length){if(!a.some(c=>c.key=='tissue')){const i=a.findIndex(c=>c.key=='vases');a.splice(i<0?a.length:i+1,0,{key:'tissue',name:'Tissue Boxes',value:'Tissue Boxes',sub:[]})}if(!a.some(c=>c.key=='marble'))a.push({key:'marble',name:'Marble & Handicraft',value:'Marble & Handicraft',sub:[]});if(!a.some(c=>c.key=='diffusers')){const i=a.findIndex(c=>c.key=='vases');a.splice(i<0?a.length:i+1,0,{key:'diffusers',name:'Aroma Diffusers',value:'Aroma Diffusers',sub:[]})}return a}}catch(e){}return defCats()}
