 if(banner){const m=$('#okm');m.style.display='block';m.innerHTML=banner}
 const dimRow=(a='',b='')=>`<div class="row"><input placeholder="Label, e.g. Height" value="${esc(a)}"><input placeholder="Value, e.g. 30 in" value="${esc(b)}"><button type="button" class="x" aria-label="Remove">×</button></div>`;
 $('#dr').innerHTML=dimRow();$('#ad').onclick=()=>$('#dr').insertAdjacentHTML('beforeend',dimRow());
 pg.addEventListener('click',e=>{const x=e.target.closest('.x');if(x&&x.parentNode.classList.contains('row'))x.parentNode.remove()});
 const photoOpts=v=>`<option value="">Auto</option>`+imgs.map((_,i)=>`<option value="${i}" ${v===String(i)?'selected':''}>Photo ${i+1}</option>`).join('');
 /* photos */
 const showImgs=()=>{$('#ims').innerHTML=imgs.map((s,i)=>`<div class="im"><img src="${s}" alt="Photo ${i+1}">${i==0?'<b>Main</b>':'<b>'+(i+1)+'</b>'}<button type="button" data-i="${i}" aria-label="Remove photo">×</button></div>`).join('');drawCol();drawMx()};
 $('#ims').onclick=e=>{const b=e.target.closest('button');if(b){imgs.splice(+b.dataset.i,1);S.colours.forEach(c=>{if(+c.photo>=imgs.length)c.photo=''});SIZES.forEach(s=>{if(+S.rows[s].photo>=imgs.length)S.rows[s].photo=''});showImgs()}};
 $('#dz').onclick=()=>$('#fi').click();
 const toJpg=f=>new Promise(res=>{const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const m=1200,s=Math.min(1,m/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*s);c.height=Math.round(im.height*s);const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0,c.width,c.height);let d=c.toDataURL('image/webp',.82);if(d.indexOf('data:image/webp')!==0)d=c.toDataURL('image/jpeg',.8);window.__imgStat=(window.__imgStat||[]).concat([[f.size,Math.round(d.length*.75)]]);res(d)};im.onerror=()=>res(null);im.src=r.result};r.onerror=()=>res(null);r.readAsDataURL(f)});
$('#fi').onchange=async e=>{window.__imgStat=[];for(const f of [...e.target.files]){if(imgs.length>=4)break;const d=await toJpg(f);if(d)imgs.push(d)}e.target.value='';showImgs();const st=window.__imgStat||[];if(st.length){const a=st.reduce((n,v)=>n+v[0],0),b=st.reduce((n,v)=>n+v[1],0),k=n=>n>1048576?(n/1048576).toFixed(1)+' MB':Math.round(n/1024)+' KB';$('#imsg').textContent='Photos optimised automatically: '+k(a)+' → '+k(b)+' (WebP, up to 1200 px).'}};
 /* colours */
